// @vitest-environment node
/**
 * SPEC-062: difusión de `assistant:update` a las ventanas desacopladas y
 * snapshot de hidratación (src/main/assistantService.ts). El asistente emite
 * por un ÚNICO despachador: el dueño de la sesión (`sender`) y, además, los
 * WebContents registrados en detachedWindowRegistry — sin doble entrega y sin
 * importar `electron` en runtime (el registro es puro).
 * Generated by QA Dev agent.
 *
 * Arnés heredado de tests/unit/assistant/assistantService.test.ts: SDK de
 * Anthropic mockeado, `electron` mockeado sin BrowserWindow (justo lo que la
 * decisión de diseño protege), store/repository REALES sobre un directorio
 * temporal y `sender` doble de WebContents.
 */
import { mkdtempSync } from 'fs'
import { tmpdir } from 'os'
import { join } from 'path'
import type { BrowserWindow, WebContents } from 'electron'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import {
  getAssistantSnapshot,
  startAssistant,
  stopAssistant
} from '../../../src/main/assistantService'
import {
  clearDetachedRegistry,
  registerDetachedWindow
} from '../../../src/main/detachedWindowRegistry'
import * as repository from '../../../src/main/db/repository'
import { initStore } from '../../../src/main/db/store'
import type { AssistantUpdateEvent } from '../../../src/renderer/src/types/assistant'

const harness = vi.hoisted(() => {
  class APIError extends Error {}
  class AuthenticationError extends APIError {}
  class RateLimitError extends APIError {}
  class APIConnectionError extends APIError {}
  return {
    create: vi.fn(),
    errors: { APIError, AuthenticationError, RateLimitError, APIConnectionError }
  }
})

vi.mock('@anthropic-ai/sdk', () => {
  class MockAnthropic {
    static APIError = harness.errors.APIError
    static AuthenticationError = harness.errors.AuthenticationError
    static RateLimitError = harness.errors.RateLimitError
    static APIConnectionError = harness.errors.APIConnectionError
    readonly messages = { create: harness.create }
  }
  return { default: MockAnthropic }
})

// Mock de electron SIN BrowserWindow: si la difusión lo usara, esta suite (y
// las 11 de main que arrancan el asistente) reventarían con un TypeError.
vi.mock('electron', () => ({
  app: {
    getPath: (): string => {
      throw new Error('app.getPath no debe usarse en tests: initStore recibe baseDir inyectado')
    }
  },
  safeStorage: {
    isEncryptionAvailable: (): boolean => true,
    encryptString: (plain: string): Buffer => Buffer.from(plain, 'utf8'),
    decryptString: (blob: Buffer): string => blob.toString('utf8')
  }
}))

interface FakeContents {
  destroyed: boolean
  send: ReturnType<typeof vi.fn>
  isDestroyed: () => boolean
}

function createContents(): FakeContents {
  const contents: FakeContents = {
    destroyed: false,
    send: vi.fn(),
    isDestroyed: () => contents.destroyed
  }
  return contents
}

/** Ventana desacoplada doble: el registro solo mira isDestroyed y webContents. */
function registerMirror(
  component: 'assistant' | 'script',
  contents: FakeContents = createContents()
): FakeContents {
  registerDetachedWindow(component, {
    isDestroyed: (): boolean => false,
    webContents: contents
  } as unknown as BrowserWindow)
  return contents
}

function assistantEvents(send: ReturnType<typeof vi.fn>): AssistantUpdateEvent[] {
  return send.mock.calls
    .filter((call) => call[0] === 'assistant:update')
    .map((call) => call[1] as AssistantUpdateEvent)
}

let interviewId = ''

beforeEach(() => {
  vi.clearAllMocks()
  clearDetachedRegistry()
  initStore(mkdtempSync(join(tmpdir(), 'maurya-detached-assistant-')))
  process.env['ANTHROPIC_API_KEY'] = 'sk-ant-test'
  const discovery = repository.createDiscovery({ name: 'Discovery Maurya' })
  interviewId = repository.createInterview({ discoveryId: discovery.id, title: 'Entrevista' }).id
})

afterEach(() => {
  stopAssistant()
  clearDetachedRegistry()
  delete process.env['ANTHROPIC_API_KEY']
})

describe('difusión del asistente a las ventanas desacopladas (SPEC-062)', () => {
  it('delivers the same event to the session owner and to every registered mirror, exactly once each', () => {
    const sender = createContents()
    const assistantMirror = registerMirror('assistant')
    const scriptMirror = registerMirror('script')

    startAssistant(sender as unknown as WebContents, interviewId)

    const ownerEvents = assistantEvents(sender.send)
    expect(ownerEvents).toHaveLength(1)
    expect(ownerEvents[0]).toEqual({
      state: 'idle',
      queue: { pending: [], pinned: [] },
      objectivesMet: []
    })
    expect(assistantEvents(assistantMirror.send)).toEqual(ownerEvents)
    expect(assistantEvents(scriptMirror.send)).toEqual(ownerEvents)
  })

  it('never delivers twice to the session owner even if it is also in the registry', () => {
    const sender = createContents()
    registerMirror('assistant', sender)

    startAssistant(sender as unknown as WebContents, interviewId)

    expect(assistantEvents(sender.send)).toHaveLength(1)
  })

  it('skips a mirror whose webContents is already destroyed', () => {
    const sender = createContents()
    const mirror = registerMirror('assistant')
    mirror.destroyed = true

    startAssistant(sender as unknown as WebContents, interviewId)

    expect(assistantEvents(sender.send)).toHaveLength(1)
    expect(mirror.send).not.toHaveBeenCalled()
  })

  it('broadcasts the no-key event through the same dispatcher', () => {
    delete process.env['ANTHROPIC_API_KEY']
    const sender = createContents()
    const mirror = registerMirror('assistant')

    startAssistant(sender as unknown as WebContents, interviewId)

    const expected: AssistantUpdateEvent = {
      state: 'no-key',
      queue: { pending: [], pinned: [] },
      objectivesMet: []
    }
    expect(assistantEvents(sender.send)).toEqual([expected])
    expect(assistantEvents(mirror.send)).toEqual([expected])
  })

  it('exposes the last emitted event as the hydration snapshot and drops it when the session stops', () => {
    const sender = createContents()

    startAssistant(sender as unknown as WebContents, interviewId)

    expect(getAssistantSnapshot()).toEqual(assistantEvents(sender.send).at(-1))

    stopAssistant()

    // El snapshot muere con la sesión: una ventana que abriese después jamás
    // debe hidratarse con la cola de la sesión anterior
    expect(getAssistantSnapshot()).toBeNull()
  })
})
